-- NutriLens — demo seed data (PostgreSQL dialect). Run schema.sql first.
--
-- Mirrors server/src/seed.js, which seeds the real MongoDB database
-- (cd server && npm run seed). Contents:
--   * 1 demo user  (alex.morgan@nutrilens.ai / password123 — demo only; change or delete it before any real use)
--   * 98 foods, 106 vegetables, 12 planner slots, 30 days of weight logs
-- Safe to re-run: it clears the seeded tables first.
-- Diet protocols are not stored in the database; they ship in
-- server/src/nutrition/diet-plans.json.

BEGIN;

TRUNCATE weight_logs, planned_meals, meal_items, meals, food_scan_items, food_scans,
         learned_food_matches, vegetables, foods, users CASCADE;

