  sodium_mg, potassium_mg, vitamin_c_mg, vitamin_a_iu, calcium_mg, iron_mg, source, source_reference, scientific_name) VALUES
  ('Carrot', 'carrot', ARRAY['Carrots', 'Gajar', 'Gajor', 'গাজর', 'Daucus carota']::text[], 'Crisp, sweet root vegetable exceptionally rich in beta-carotene (provitamin A), lutein, and dietary fiber.', 'Vibrant orange tapered cylindrical taproot with subtle horizontal lenticel rings, crisp solid core, and feathery green crown.', 'orange', ARRAY['green']::text[], 'tapered_cylindrical', 70, 29, '1 medium carrot (~70g = 29 kcal)', 'Root Vegetables', 'https://images.unsplash.com/photo-1598170845058-32b9d6a5da37?w=600&auto=format&fit=crop&q=80', 41, 0.9, 9.6, 0.2, 2.8, 4.7, 69, 320, 5.9, 16706, 33, 0.3, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170393 (Carrots, raw)', 'Daucus carota'),
  ('Potato', 'potato', ARRAY['Potatoes', 'Aloo', 'Alu', 'White Potato', 'আলু', 'Solanum tuberosum']::text[], 'Starchy edible tuber providing complex carbohydrates, potassium, and vitamin C in its raw edible flesh.', 'Rounded to oval earthy tuber with thin light-brown skin, shallow eyes, and starchy cream-to-pale-yellow flesh.', 'brown', ARRAY['yellow', 'white']::text[], 'round', 170, 131, '1 medium potato (~170g = 131 kcal)', 'Root Vegetables', 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?w=600&auto=format&fit=crop&q=80', 77, 2, 17.5, 0.1, 2.1, 0.8, 6, 421, 19.7, 2, 12, 0.8, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170026 (Potatoes, raw)', 'Solanum tuberosum'),
  ('Sweet Potato', 'sweet-potato', ARRAY['Sweet Potatoes', 'Shakarkand', 'Misti Aloo', 'মিষ্টি আলু', 'Yam (US)', 'Ipomoea batatas']::text[], 'Naturally sweet, nutrient-dense tuber high in complex carbs, dietary fiber, beta-carotene, and potassium.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/sweet-potato.webp', 86, 1.6, 20.1, 0.1, 3, 4.2, 55, 337, 2.4, 14187, 30, 0.6, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 168482 (Sweet potato, raw)', 'Ipomoea batatas'),
  ('Beetroot', 'beetroot', ARRAY['Beet', 'Beets', 'Chukandar', 'বিট', 'Beta vulgaris']::text[], 'Earthy, vibrant red taproot loaded with dietary nitrates, folate, manganese, and antioxidants like betalains.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/beetroot.webp', 43, 1.6, 9.6, 0.2, 2.8, 6.8, 78, 325, 4.9, 33, 16, 0.8, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169145 (Beets, raw)', 'Beta vulgaris'),
  ('Radish', 'radish', ARRAY['Daikon', 'Red Radish', 'Mooli', 'Mula', 'মুলা', 'Raphanus sativus']::text[], 'Crisp, peppery root vegetable with high moisture content and glucosinolate antioxidants.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/radish.webp', 16, 0.7, 3.4, 0.1, 1.6, 1.9, 39, 233, 14.8, 7, 25, 0.3, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169276 (Radishes, raw)', 'Raphanus sativus'),
  ('Turnip', 'turnip', ARRAY['Turnips', 'Shalgam', 'শালগম', 'Brassica rapa subsp. rapa']::text[], 'White-and-purple bulbous root vegetable with mildly spicy, sweet flesh rich in vitamin C.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/turnip.webp', 28, 0.9, 6.4, 0.1, 1.8, 3.8, 67, 191, 21, 0, 30, 0.3, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170460 (Turnips, raw)', 'Brassica rapa subsp. rapa'),
  ('Parsnip', 'parsnip', ARRAY['Parsnips', 'Pastinaca sativa']::text[], 'Cream-colored taproot closely related to carrot with a sweet, nutty, herbal flavor and high soluble fiber.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/parsnip.webp', 75, 1.2, 18, 0.3, 4.9, 4.8, 10, 375, 17, 0, 36, 0.6, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170438 (Parsnips, raw)', 'Pastinaca sativa'),
  ('Rutabaga', 'rutabaga', ARRAY['Swede', 'Yellow Turnip', 'Brassica napus napobrassica']::text[], 'Hearty root vegetable formed by crossing turnip and wild cabbage, with dense, slightly sweet yellow flesh.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/rutabaga.webp', 37, 1.1, 8.6, 0.2, 2.3, 4.5, 12, 305, 25, 2, 43, 0.4, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170443 (Rutabagas, raw)', 'Brassica napobrassica'),
  ('Celeriac', 'celeriac', ARRAY['Celery Root', 'Knob Celery', 'Turnip-rooted Celery']::text[], 'Knobby root variety of celery with crisp, aromatic flesh ideal for low-carb purées and raw slaws.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/celeriac.webp', 42, 1.5, 9.2, 0.3, 1.8, 1.6, 100, 300, 8, 0, 43, 0.7, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170397 (Celeriac, raw)', 'Apium graveolens var. rapaceum'),
  ('Horseradish', 'horseradish', ARRAY['Horseradish Root', 'Armoracia rusticana']::text[], 'Pungent, intensely spicy root used as a zesty condiment with natural sinus-clearing isothiocyanates.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Root Vegetables', '/vegetables/horseradish.webp', 48, 1.2, 11.3, 0.7, 3.3, 7.9, 420, 246, 24.9, 2, 56, 0.4, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170417 (Horseradish, raw)', 'Armoracia rusticana'),
  ('Taro Root', 'taro-root', ARRAY['Taro', 'Eddoe', 'Arbi', 'Kochu', 'Mukhi Kochu', 'কচু', 'Colocasia esculenta']::text[], 'Starchy tropical corm with a nutty, mild flavor, rich in dietary fiber, potassium, and resistant starch.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/taro-root.webp', 112, 1.5, 26.5, 0.2, 4.1, 0.4, 11, 591, 4.5, 76, 43, 0.6, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 168485 (Taro, raw)', 'Colocasia esculenta'),
  ('Elephant Foot Yam', 'elephant-foot-yam', ARRAY['Jimikand', 'Suran', 'Ol Kochu', 'ওল কচু', 'Amorphophallus paeoniifolius']::text[], 'Large, earthy tropical tuber widely consumed across South Asia for its rich fiber and complex carbohydrates.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/elephant-foot-yam.webp', 79, 1.4, 18.2, 0.1, 3.8, 0.5, 14, 410, 12, 18, 50, 0.7, 'USDA FoodData Central', 'USDA / ICMR Food Composition Tables (Elephant Yam, raw)', 'Amorphophallus paeoniifolius'),
  ('Cassava', 'cassava', ARRAY['Yuca', 'Manioc', 'Shimul Alu', 'শিমুল আলু', 'Manihot esculenta']::text[], 'Nutrient-rich starchy tropical root that serves as a vital staple food source of energy and vitamin C.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/cassava.webp', 160, 1.4, 38.1, 0.3, 1.8, 1.7, 14, 271, 20.6, 13, 16, 0.3, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169385 (Cassava, raw)', 'Manihot esculenta'),
  ('Yam', 'yam', ARRAY['True Yam', 'Dioscorea', 'Khamalu', 'Ratalu']::text[], 'True botanical yam tuber with thick rough skin and dense, starchy flesh rich in manganese and vitamin B6.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/yam.webp', 118, 1.5, 27.9, 0.2, 4.1, 0.5, 9, 816, 17.1, 138, 17, 0.5, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170071 (Yam, raw)', 'Dioscorea alata'),
  ('Jerusalem Artichoke', 'jerusalem-artichoke', ARRAY['Sunchoke', 'Sunroot', 'Helianthus tuberosus']::text[], 'Knobby sunflower tuber exceptionally rich in prebiotic inulin fiber that nourishes gut microbiome bacteria.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/jerusalem-artichoke.webp', 73, 2, 17.4, 0, 1.6, 9.6, 4, 429, 4, 20, 14, 3.4, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169244 (Jerusalem-artichokes, raw)', 'Helianthus tuberosus'),
  ('Lotus Root', 'lotus-root', ARRAY['Kamal Kakdi', 'Padma Mool', 'পদ্ম মূল', 'Nelumbo nucifera']::text[], 'Crisp underwater rhizome with a striking lace-wheel cross-section, loaded with fiber and vitamin C.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/lotus-root.webp', 74, 2.6, 17.2, 0.1, 4.9, 0.5, 40, 556, 44, 0, 45, 1.2, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169248 (Lotus root, raw)', 'Nelumbo nucifera'),
  ('Water Chestnut', 'water-chestnut', ARRAY['Chinese Water Chestnut', 'Singhara', 'Paniphal', 'পানিফল', 'Eleocharis dulcis']::text[], 'Aquatic tuber with crispy white flesh that retains its crunchy texture even after cooking.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Tubers & Corms', '/vegetables/water-chestnut.webp', 97, 1.4, 23.9, 0.1, 3, 4.8, 14, 584, 4, 0, 11, 0.6, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169308 (Waterchestnuts, chinese, raw)', 'Eleocharis dulcis'),
  ('Broccoli', 'broccoli', ARRAY['Broccoli Florets', 'Calabrese', 'ব্রকলি', 'Brassica oleracea var. italica']::text[], 'Prized cruciferous vegetable packed with sulforaphane, vitamin C, vitamin K, and protective indoles.', 'Tree-like cruciferous head with densely clustered emerald-to-sage green bead buds atop a pale jade fibrous stem.', 'green', ARRAY['white']::text[], 'floret_cluster', 91, 31, '1 cup florets (~91g = 31 kcal)', 'Cruciferous', 'https://images.unsplash.com/photo-1459411621453-7b03977f4bfc?w=600&auto=format&fit=crop&q=80', 34, 2.8, 6.6, 0.4, 2.6, 1.7, 33, 316, 89.2, 623, 47, 0.7, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170379 (Broccoli, raw)', 'Brassica oleracea var. italica'),
  ('Cauliflower', 'cauliflower', ARRAY['Phool Gobhi', 'Fulkopi', 'ফুলকপি', 'Brassica oleracea var. botrytis']::text[], 'Versatile, mild white cruciferous vegetable popular as a low-carb grain substitute and fiber source.', 'Compact, rounded creamy-white dense curd head surrounded by thick ribbed green protective leaves.', 'white', ARRAY['green']::text[], 'floret_cluster', 100, 25, '1 cup chopped (~100g = 25 kcal)', 'Cruciferous', 'https://images.unsplash.com/photo-1568584711075-3d021a7c3ca3?w=600&auto=format&fit=crop&q=80', 25, 1.9, 5, 0.3, 2, 1.9, 30, 299, 48.2, 0, 22, 0.4, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169986 (Cauliflower, raw)', 'Brassica oleracea var. botrytis'),
  ('Cabbage', 'cabbage', ARRAY['Green Cabbage', 'Bandhakopi', 'Patta Gobhi', 'বাঁধাকপি', 'Brassica oleracea var. capitata']::text[], 'Dense leafy green head vegetable loaded with vitamin K, vitamin C, and anti-inflammatory glutamine.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Cruciferous', '/vegetables/cabbage.webp', 25, 1.3, 5.8, 0.1, 2.5, 3.2, 18, 170, 36.6, 98, 40, 0.5, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169975 (Cabbage, raw)', 'Brassica oleracea var. capitata'),
  ('Red Cabbage', 'red-cabbage', ARRAY['Purple Cabbage', 'Lal Bandhakopi', 'লাল বাঁধাকপি']::text[], 'Vibrant purple-red cabbage packed with powerful anthocyanin polyphenols and double the iron of green cabbage.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Cruciferous', '/vegetables/red-cabbage.webp', 31, 1.4, 7.4, 0.2, 2.1, 3.8, 27, 243, 57, 1116, 45, 0.8, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 169977 (Cabbage, red, raw)', 'Brassica oleracea var. capitata f. rubra'),
  ('Brussels Sprouts', 'brussels-sprouts', ARRAY['Brussels Sprout', 'Brassica oleracea var. gemmifera']::text[], 'Miniature cabbage-like cruciferous buds high in protein for greens, vitamin K, and glucosinolates.', '', 'green', '{}'::text[], 'irregular', 100, 0, '1 medium piece (~100g)', 'Cruciferous', '/vegetables/brussels-sprouts.webp', 43, 3.4, 9, 0.3, 3.8, 2.2, 25, 389, 85, 754, 42, 1.4, 'USDA FoodData Central', 'USDA FoodData Central FDC ID: 170383 (Brussels sprouts, raw)', 'Brassica oleracea var. gemmifera'),
